#!/usr/bin/env bash
# Generated by infx-bench-script-generator for dsv4_vllm_mi355x-fp4-mtp_agentic :: override_tp8_c56
# Run on the HOST. Starts a long-lived ROCm container; scripts 02/03 run inside it.
# Env vars deliberately live in 02_start_server.sh / 03_run_client.sh, not here.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

CONTAINER_NAME="infx-bench-dsv4-tp8_c56"
IMAGE="vllm/vllm-openai-rocm:nightly-e9757321527ca1ecd514c07c1418dd2c53da3d19"

# ---- mounts (host -> container) ----
#   model:   named volume; 02_start_server.sh downloads weights once
#   repo:    named volume; 03_run_client.sh clones InferenceX once
#   dataset: reuses host HF cache + token; client downloads the trace dataset if missing
#   results: named volume; InferenceX default RESULT_DIR=/logs/agentic

docker rm -f "$CONTAINER_NAME" >/dev/null 2>&1 || true

docker run -d --name "$CONTAINER_NAME" \
  --network host --ipc host \
  --device /dev/kfd --device /dev/dri --group-add video \
  --cap-add SYS_PTRACE --security-opt seccomp=unconfined \
  --entrypoint /bin/sleep \
  -v "${CONTAINER_NAME}-model:/model" \
  -v "${CONTAINER_NAME}-repo:/infmax-workspace" \
  -v "$HOME/.cache/huggingface:/hf-cache" \
  -v "${CONTAINER_NAME}-logs:/logs" \
  -v "$SCRIPT_DIR:/infx-scripts:ro" \
  "$IMAGE" infinity

cat <<EOF
Container '$CONTAINER_NAME' started ($IMAGE).

Next steps:
  1. docker exec -it $CONTAINER_NAME bash /infx-scripts/02_start_server.sh
  2. docker exec -it $CONTAINER_NAME bash /infx-scripts/03_run_client.sh

Inspect server logs: docker exec $CONTAINER_NAME tail -f /logs/server.log
Stop it later:       docker rm -f $CONTAINER_NAME
EOF
